    var old = btn.dataset.t || btn.textContent;
    btn.dataset.t = old;
    copyText(t).then(function () {
      btn.textContent = '✓ کپی شد';
      toast('PGN کپی شد.');
    }, function () {
      window.prompt('کپی خودکار نشد؛ متن را دستی کپی کن:', t);
    }).then(function () {
      setTimeout(function () { btn.textContent = old; }, 1500);
    });
  }

  function mk(getX) {
    var b = document.createElement('button');
    b.type = 'button'; b.className = 'gxcp'; b.textContent = '📋 کپی PGN';
    b.onclick = function (e) { e.stopPropagation(); doCopy(getX(), b); };
    return b;
  }

  // نمودار دسته‌ی اصلی
  var zo = document.getElementById('gvzo');
  if (zo) zo.insertAdjacentElement('beforebegin', mk(function () { return GV; }));

  // نمودارهای داخل ویرایش و مرور
  ['e', 'v'].forEach(function (k) {
    var w = document.getElementById('gxw_' + k);
    var tb = w && w.querySelector('.gvtb');
    if (tb) tb.appendChild(mk(function () { return GX[k]; }));
  });
})();

