  window.__LINER_RVAN = 1;

  var flip = document.getElementById('rflip');
  var main = document.getElementById('rfree');
  if (!flip || !main) throw new Error('عناصر مرور پیدا نشد');

  // دکمه‌ی جدید: درست بعد از دکمه‌ی چرخش، در همان ردیف جلو/عقب
  var b = document.createElement('button');
  b.id = 'rfree2';
  b.type = 'button';
  b.textContent = 'تحلیل';
  b.onclick = function () { main.onclick(); sync(); };
  flip.insertAdjacentElement('afterend', b);

  // همگام نگه داشتن متن/حالت دو دکمه (تحلیل ↔ پایان تحلیل)
  function sync() {
    b.textContent = main.textContent;
    b.classList.toggle('on', main.classList.contains('on'));
  }
  if (typeof window.upRv === 'function') {
    var _upRv = window.upRv;
    window.upRv = function () {
      var r = _upRv.apply(this, arguments);
      sync();
      return r;
    };
  }
  sync();
})();
